#!/usr/bin/env ruby
require'json';require'open3';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);build=File.join(client,'build/web-desktop');ts=File.read(File.join(client,'tsconfig.json'));ignore=File.read(File.join(client,'.gitignore'));out,err,status=Open3.capture3('rg','-n','-i','--glob','!**/*.map','(?:qh|QH|127\\.0\\.0\\.1|localhost|ws://|http://)',build);hits=out.lines.first(200).map{|line|line.sub(client+'/','')};checks={excludedFromTypeScript:ts.include?('"build"'),ignoredFromSource:ignore.lines.map(&:strip).include?('/build/'),notReleaseInput:!File.read(File.join(root,'config/release-allowlist.json')).include?('../Client/build'),noLegacyAddressOrBrand:hits.empty?};report={schemaVersion:1,checks:checks,hitCount:out.lines.length,hits:hits,verdict:checks.values.all? ? 'passed':'blocked-stale-generated-build'};path=File.join(root,'docs/generated/creal04-web-build.json');FileUtils.mkdir_p(File.dirname(path));File.write(path,JSON.pretty_generate(report)+"\n");puts "CREAL04 AUDITED: #{report[:verdict]}, #{out.lines.length} old-address/brand hits"
